Here is the root cause:
In `nfsd4_add_rdaccess_to_wrdeleg()`, when a client already holds a SHARE_ACCESS_READ open, the function unconditionally overwrites `fp->fi_fds[O_RDONLY]` with a newly acquired `nfsd_file` without releasing the existing reference, orphaning it. Additionally, the same `nfsd_file` pointer is assigned to both `fp->fi_fds[O_RDONLY]` and `fp->fi_rdeleg_file` with only a single reference count. In `put_deleg_file()`, the reference is released via `nfs4_file_put_access()` which only decrements `fi_fds[O_RDONLY]` when the `fi_access[O_RDONLY]` counter drops to zero. If another READ open keeps the counter positive, the delegation's reference is never released, causing a leak. This leads to files with elevated reference counts that cannot be cleaned up on server shutdown, triggering a BUG() in `kmem_cache_destroy()`.

Here is the patch:

 static void put_deleg_file(struct nfs4_file *fp)
 {
 	struct nfsd_file *rnf = NULL;
 	struct nfsd_file *nf = NULL;

 	spin_lock(&fp->fi_lock);
 	if (--fp->fi_delegees == 0) {
 		swap(nf, fp->fi_deleg_file);
 		swap(rnf, fp->fi_rdeleg_file);
 	}
 	spin_unlock(&fp->fi_lock);

 	if (nf)
 		nfsd_file_put(nf);
-	if (rnf)
+	if (rnf) {
+		nfsd_file_put(rnf);
 		nfs4_file_put_access(fp, NFS4_SHARE_ACCESS_READ);
+	}
 }

  */
 static bool
 nfsd4_add_rdaccess_to_wrdeleg(struct svc_rqst *rqstp, struct nfsd4_open *open,
 			      struct svc_fh *fh, struct nfs4_ol_stateid *stp)
 {
 	struct nfs4_file *fp;
 	struct nfsd_file *nf = NULL;

 	if ((open->op_share_access & NFS4_SHARE_ACCESS_BOTH) ==
 			NFS4_SHARE_ACCESS_WRITE) {
 		if (nfsd_file_acquire_opened(rqstp, fh, NFSD_MAY_READ, NULL, &nf))
 			return (false);
 		fp = stp->st_stid.sc_file;
 		spin_lock(&fp->fi_lock);
 		__nfs4_file_get_access(fp, NFS4_SHARE_ACCESS_READ);
-		fp = stp->st_stid.sc_file;
-		fp->fi_fds[O_RDONLY] = nf;
-		fp->fi_rdeleg_file = nf;
+		if (!fp->fi_fds[O_RDONLY]) {
+			fp->fi_fds[O_RDONLY] = nf;
+			nf = NULL;
+		}
+		fp->fi_rdeleg_file = nfsd_file_get(fp->fi_fds[O_RDONLY]);
 		spin_unlock(&fp->fi_lock);
+		if (nf)
+			nfsd_file_put(nf);
 	}
 	return true;
 }



